# -*- coding: utf-8 -*-
from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
O=[['拉丁 onus，属格 oneris','负担、重担；词干 oner-']]
X=O+[['拉丁 onerare → exonerare','装上负担 → ex- 向外，卸下负担']]
W=[E('onus','英 /ˈəʊnəs/；美 /ˈoʊnəs/','责任；负担〔正式〕','这件事轮到谁来做、谁来证明，担子就落在谁身上。','直接借拉丁 onus“负担”。它的属格是 oneris，所以同族另一些词出现 oner-；不是英语 one“一个”的变体。',O+[['英语 onus','必须承担的责任或证明任务']],'The onus is on you to check，意思是“检查这件事由你负责”。它把责任说成压在肩上的担子，常用于明确分工或指出谁有责任提出证明，并不一定是在责怪已经犯错的人。','the onus is on somebody to do something；put/place the onus on somebody；the onus of proof。','responsibility 是通用的责任；onus 更强调某项负担落在谁身上，语体较正式。',('The onus is on the supplier to explain any delay.','供应商有责任解释任何延误。'),('The new process puts the onus on each team to check its own figures.','新流程要求各团队负责核查自己的数据。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/onus','https://www.etymonline.com/word/onus']),
E('onerous','英 /ˈəʊnərəs/；美 /ˈɑːnərəs/，亦 /ˈoʊnərəs/','繁重的；费力的；苛重的','担子太重，做起来很费时间、精力或钱。','来自拉丁 onerosus“负担重的”，经法语或直接借入英语。现代可认出 oner- + -ous，但不是较晚的英语 onus 先产生、再现造这个词。',O+[['拉丁 onerosus','负担沉重的'],['古法语 onereus／直接拉丁借入 → 英语 onerous','繁重、难以承受的']],'它可以说工作本身很费力，也能说合同条款、手续或要求把人压得很累。Onerous conditions 不一定违法，而是履行起来负担很大。','an onerous task；onerous duties；onerous conditions/requirements。','difficult 可以只是技术上难；onerous 侧重沉重负担，比如每周填大量重复表格，未必难懂，却很耗人。',('Completing six separate reports every Friday became an onerous task.','每周五分别完成六份报告，成了一项繁重的任务。'),('Small firms struggled to meet the contract’s onerous conditions.','小公司很难满足合同中负担沉重的条件。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/onerous','https://www.etymonline.com/word/onerous']),
E('exonerate','英 /ɪɡˈzɒnəreɪt/；美 /ɪɡˈzɑːnəreɪt/','洗清指控；证明无责〔正式〕','把压在某人身上的“这事怪你”卸下来。','拉丁 ex-“向外” + onerare“装上负担”形成 exonerare“卸下负担”；英语接其分词词干 exonerat-。原来的卸重物，发展为解除责难和指控。',X+[['拉丁分词 exoneratus → 英语 exonerate','卸下负担 → 洗清责难、指控']],'一开始有人认为事故是某人造成的，后来记录或调查显示他并无责任，就可以说这些证据 exonerate him。这个词不限于法庭，也可用于工作或公共事件的调查。','exonerate somebody；exonerate somebody of/from blame；evidence that exonerates somebody。','forgive 是原谅，即使对方确实犯了错也能原谅；exonerate 是洗清责任或指控，重点在澄清“并不是他的错”。',('The server logs exonerated the technician who had been blamed for the outage.','服务器日志洗清了那名被指责造成断网的技术员的责任。'),('An independent investigation exonerated the team of any wrongdoing.','独立调查证明该团队没有任何不当行为。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/exonerate','https://www.etymonline.com/word/exonerate']),
E('exoneration','英 /ɪɡˌzɒnəˈreɪʃən/；美 /ɪɡˌzɑːnəˈreɪʃən/','洗清指控；澄清无责；平反','担子卸掉后，得到“没有这项责任或罪责”的澄清。','现代可与 exonerate + -ion 配对；历史上英语名词另接晚期拉丁 exoneratio（宾格 exonerationem）“卸下、减轻负担”，来自 exonerare。不是一定先有英语动词才造名词。',X+[['晚期拉丁 exoneratio / exonerationem','卸下、减轻负担'],['英语 exoneration','洗清指控或责难']],'它可以指澄清的过程，也可指得到的无责结论。工作调查里的 full exoneration 就是彻底洗清责任；在司法语境中可译“平反”，但单纯获释或某次指控被撤回，不能不看背景就都叫 exoneration。','the exoneration of somebody；full/complete exoneration；lead to somebody’s exoneration。','explanation 只是解释，解释未必能洗清责任；exoneration 强调责难已被澄清。',('The final report amounted to a complete exoneration of the staff.','最终报告实际上彻底洗清了员工们的责任。'),('The discovery of the original records led to her exoneration.','原始记录的发现使她洗清了指控。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/exoneration','https://www.etymonline.com/word/exoneration'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C0889');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C0889');keep={w['word']for w in W};excluded={w:'按用户当前范围暂略：罕见派生词。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C0889',meaning='负担；重担',core='oner- 可以想成压在肩上的一副担子。',image='onus 指谁承担；onerous 说担子很重；exonerate 把责难这副担子卸掉。',intro='物理上的重量，进入抽象领域就成为责任、繁重要求和指控。把担子是“落下来”还是“卸掉”想清楚，四个词就容易分开。',forms='拉丁 onus“负担”，属格 oneris，派生词常用 oner-；exonerare 中 ex- 表示向外、除去。',branches=[['承担与负担','onus、onerous'],['卸下责难','exonerate、exoneration']],contrasts='onus、onerous 和 exoneration 有各自的借入历史，不应把所有词都画成从现代英语 onus 一个接一个造出。',practice='先用 onus 说明谁负责核查，再用 onerous 评价核查任务；如果证据洗清了责任，才用 exonerate。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/onus','https://www.etymonline.com/word/onerous','https://www.etymonline.com/word/exonerate','https://www.etymonline.com/word/exoneration'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_218_oner.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0889',len(W),'new')
